   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你走进店内，房间中央是一张厚重的橡木桌，桌面上铺着深紫色的绒布，垂到桌沿。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_905.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="桌上摆放着一颗水晶球，拳头大小，通体透明，内部似乎有雾气在缓缓流动。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_905.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="桌后坐着一个白发女子，穿着深色的斗篷。兜帽遮住了大半个额头，脸上戴着半截白色面纱，只露出一双眼睛。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_905.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [81]={next_id=82, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虽然女人经过精心的乔装打扮，但你还是第一眼就认出了她——蒂雅。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_905.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
